(async function () {
  const root=document.getElementById('activity-root');
  try { const data=await fetch(window.activityDataUrl).then(r=>r.json()); const pieces=shuffleChoices(data.sequence), isLearning=window.activityMode==='learn';
    root.innerHTML=`<h1>${data.title || 'Put it in order'}</h1><span class="mode-label ${isLearning ? 'learn' : 'challenge'}">${isLearning ? '🌱 Learning time — hints are on!' : '🏆 Challenge time — no hints!'}</span><p class="instruction">Drag the letters into the correct order.</p><div class="sequence pieces">${pieces.map((x,i)=>`<div class="draggable" draggable="true" data-value="${x}" id="piece-${i}">${x}</div>`).join('')}</div><div class="sequence zones">${data.correct.map((_,i)=>`<div class="drop-zone" data-index="${i}">?</div>`).join('')}</div><p class="feedback"></p><button class="try-again">Try again</button>`;
    let dragged; root.querySelectorAll('.draggable').forEach(x=>{x.addEventListener('dragstart',e=>{dragged=x;e.dataTransfer.setData('text/plain',x.dataset.value)});x.addEventListener('touchstart',()=>dragged=x,{passive:true});}); root.querySelectorAll('.drop-zone').forEach(zone=>{zone.addEventListener('dragover',e=>e.preventDefault());zone.addEventListener('drop',e=>{e.preventDefault();place(zone)});zone.addEventListener('click',()=>{if(dragged)place(zone)});});
    function place(zone){if(!dragged||zone.textContent!=='?')return;const piece=dragged, value=piece.dataset.value;zone.textContent=value;piece.style.visibility='hidden';dragged=null;if(isLearning&&value!==data.correct[zone.dataset.index]){zone.classList.add('wrong');root.querySelector('.feedback').textContent='';root.querySelector('.feedback').className='feedback error';kidsFun.tryAgain(root);setTimeout(()=>{zone.textContent='?';zone.classList.remove('wrong');piece.style.visibility='visible';piece.classList.add('returning');setTimeout(()=>piece.classList.remove('returning'),600)},650);return;}if([...root.querySelectorAll('.drop-zone')].every(z=>z.textContent!=='?'))check();}
    function check(){let ok=true;root.querySelectorAll('.drop-zone').forEach((z,i)=>{const good=z.textContent===data.correct[i];z.classList.add(good?'correct':'wrong');if(!good && isLearning){z.classList.add('answer');z.textContent=data.correct[i];}ok&&=good;});const f=root.querySelector('.feedback');f.textContent='';f.className='feedback '+(ok?'success':'error');if(ok)kidsFun.celebrate(root,'Good job! Fantastic sequencing!');else kidsFun.tryAgain(root);}
    root.querySelector('.try-again').addEventListener('click',()=>{root.querySelectorAll('.draggable').forEach(piece=>{piece.style.visibility='visible';piece.classList.add('returning');setTimeout(()=>piece.classList.remove('returning'),600)});root.querySelectorAll('.drop-zone').forEach(zone=>{zone.textContent='?';zone.className='drop-zone'});root.querySelector('.feedback').textContent='';});
  } catch {root.innerHTML='<h1>Oops!</h1><p class="instruction">This activity could not be loaded.</p>';}
}());
